  function dayKey(value){const date=new Date(value);return Number.isNaN(date.getTime())?'':`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
  function activityByDay(){const days={};const ensure=(date)=>{const k=dayKey(date);if(!k)return null;days[k]=days[k]||{date:k,minutes:0,lessons:0,reviews:0,practices:0,tests:0};return days[k];};(app.PracticeService?.getHistory?.()||[]).forEach((attempt)=>{const day=ensure(attempt.completedAt||attempt.createdAt);if(day){day.minutes+=Math.max(1,Math.round(Number(attempt.durationSeconds||0)/60));day.practices+=1;if(String(attempt.setId||'').includes('topik')||String(attempt.source||'').includes('exam'))day.tests+=1;}});FocusSessionService.all().filter((item)=>item.status==='completed').forEach((session)=>{const day=ensure(session.completedAt);if(day)day.minutes+=Number(session.actualMinutes||0);});Object.values(state.lessonProgress||{}).forEach((lesson)=>{if(lesson.completed&&lesson.updatedAt){const day=ensure(lesson.updatedAt);if(day){day.lessons+=1;day.minutes+=Math.max(5,Number(lesson.studyMinutes||0));}}});return days;}
