  function studyCalendarView(){const month=runtime.calendarMonth;const year=month.getFullYear(),monthIndex=month.getMonth();const firstOffset=new Date(year,monthIndex,1).getDay();const daysInMonth=new Date(year,monthIndex+1,0).getDate();const activity=activityByDay();const selected=activity[runtime.calendarDay];const cells=[...Array(firstOffset).fill(null),...Array.from({length:daysInMonth},(_,i)=>i+1)];const monthLabel=new Intl.DateTimeFormat(lang()==='zh-CN'?'zh-CN':lang(),{month:'long',year:'numeric'}).format(month);return `<section class="section page-heading"><button class="back-link" data-view="profile">← ${escapeHtml(localize({vi:'Hồ sơ',en:'Profile','zh-CN':'个人资料'}))}</button><p class="eyebrow">Study Calendar</p><h1 class="headline">${escapeHtml(localize({vi:'Lịch học tập',en:'Study calendar','zh-CN':'学习日历'}))}</h1></section><section class="calendar-shell section"><header><button data-calendar-shift="-1">←</button><h2>${escapeHtml(monthLabel)}</h2><button data-calendar-shift="1">→</button></header><div class="calendar-weekdays">${(lang()==='vi'?['CN','T2','T3','T4','T5','T6','T7']:lang()==='zh-CN'?['日','一','二','三','四','五','六']:['S','M','T','W','T','F','S']).map((item)=>`<span>${item}</span>`).join('')}</div><div class="calendar-grid">${cells.map((day)=>{if(!day)return'<span></span>';const k=`${year}-${String(monthIndex+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const minutes=activity[k]?.minutes||0;const intensity=minutes>=60?4:minutes>=30?3:minutes>=10?2:minutes>0?1:0;return `<button class="heat-${intensity} ${runtime.calendarDay===k?'selected':''}" data-calendar-day="${k}" aria-label="${k}: ${minutes} minutes"><b>${day}</b>${minutes?`<small>${minutes}′</small>`:''}</button>`;}).join('')}</div><div class="heat-legend"><span>0</span><i class="heat-1"></i><span>&lt;10′</span><i class="heat-2"></i><span>10–30′</span><i class="heat-3"></i><span>30–60′</span><i class="heat-4"></i><span>60+′</span></div></section>${selected?`<section class="calendar-day-detail section"><h2>${dateLabel(`${selected.date}T12:00:00`)}</h2><div><span><b>${selected.minutes}</b>${escapeHtml(localize({vi:'phút',en:'minutes','zh-CN':'分钟'}))}</span><span><b>${selected.lessons}</b>lessons</span><span><b>${selected.practices}</b>practices</span><span><b>${selected.tests}</b>tests</span></div></section>`:''}`;}

  const MilestoneService={all(){return readValue(key('milestones'),[]);},refresh(){const current=this.all();const existing=new Set(current.map((item)=>item.id));const progress=getUserProgress();const history=app.PracticeService?.getHistory?.()||[];const checkpoints=CheckpointService.all();const mastered=(state.srsData||[]).filter((item)=>item.status==='mastered').length;const candidates=[{id:'started',type:'started',reached:state.currentUser?.createdAt,title:{vi:'Bắt đầu học tiếng Hàn',en:'Started learning Korean','zh-CN':'开始学习韩语'}},{id:'vocab-50',type:'vocabulary',reached:mastered>=50?now():null,title:{vi:'50 từ đã thành thạo',en:'50 mastered words','zh-CN':'掌握 50 个单词'}},{id:'vocab-100',type:'vocabulary',reached:mastered>=100?now():null,title:{vi:'100 từ đã thành thạo',en:'100 mastered words','zh-CN':'掌握 100 个单词'}},{id:'first-mock',type:'exam',reached:history[history.length-1]?.completedAt||null,title:{vi:'Hoàn thành bài thi thử đầu tiên',en:'Completed the first mock test','zh-CN':'完成第一次模拟考试'}},{id:'streak-7',type:'streak',reached:Number(progress.stats?.streak||0)>=7?now():null,title:{vi:'Duy trì 7 ngày liên tiếp',en:'Reached a 7-day streak','zh-CN':'连续学习 7 天'}},{id:'days-30',type:'days',reached:Number(progress.stats?.learningDays||0)>=30?now():null,title:{vi:'30 ngày học có hoạt động',en:'30 active learning days','zh-CN':'30 个有效学习日'}},{id:'checkpoint-mastered',type:'checkpoint',reached:checkpoints.find((item)=>item.overall>=80)?.completedAt||null,title:{vi:'Mastered một checkpoint',en:'Mastered a checkpoint','zh-CN':'掌握一个章节检查点'}}];const additions=candidates.filter((item)=>item.reached&&!existing.has(item.id)).map((item)=>({...item,userId:uid(),reachedAt:item.reached,metadata:{derived:true}}));if(additions.length)writeValue(key('milestones'),[...current,...additions].sort((a,b)=>new Date(a.reachedAt)-new Date(b.reachedAt)),'milestones');return additions.length?[...current,...additions]:current;}};
  function progressTimelineView(){const milestones=MilestoneService.refresh().sort((a,b)=>new Date(b.reachedAt)-new Date(a.reachedAt));return `<section class="section page-heading"><button class="back-link" data-view="profile">← ${escapeHtml(localize({vi:'Hồ sơ',en:'Profile','zh-CN':'个人资料'}))}</button><p class="eyebrow">Progress Timeline</p><h1 class="headline">${escapeHtml(localize({vi:'Hành trình học',en:'Learning journey','zh-CN':'学习历程'}))}</h1><p class="subtle">${escapeHtml(localize({vi:'Chỉ hiển thị cột mốc suy ra từ tiến độ thật; mỗi cột mốc chỉ được lưu một lần.',en:'Only milestones derived from real progress are shown, and each is stored once.','zh-CN':'仅显示由真实进度推导的里程碑，每项只保存一次。'}))}</p></section><ol class="progress-timeline section">${milestones.length?milestones.map((item)=>`<li><span>✓</span><div><small>${dateLabel(item.reachedAt)}</small><h2>${escapeHtml(localize(item.title))}</h2><p>${escapeHtml(item.type)}</p></div></li>`).join(''):`<li><span>·</span><div><h2>${tr('empty')}</h2></div></li>`}</ol>`;}

